sys_variable_value.value:
(function execute(inputs, outputs) {
    // Extract the BRL value as a string from the input object
    var brlString = inputs.object.data.BRL;

    // Convert the BRL value to a float
    var brlFloat = parseFloat(brlString);

    // Round to two decimal places and set the output
    outputs.brlrate = brlFloat.toFixed(2); 
    // outputs.usdvalue = parseFloat(current.input_variables.amount_in_brl)/ brlFloat.toFixed(2); 

})(inputs, outputs);

